-- Adds 1 new Module 7 lesson covering the two genuine gaps found after
-- re-reading this module's (excellent, pre-existing) prose closely for the
-- first time: copyright/IP over AI training data and AI-generated output,
-- and the environmental/compute cost of AI. Neither was covered anywhere in
-- the academy. Both are standard ethics-of-AI topics that matter specifically
-- for people who will actually build with generative AI.
--
-- Anchored to a lesson title via subquery, safe regardless of current
-- numbering. Placed BEFORE "Your Path Forward" so that stays the true
-- closing/capstone lesson of the whole academy.

UPDATE public.lessons SET order_index = -order_index
WHERE order_index >= (SELECT order_index FROM public.lessons WHERE module_number = 7 AND title = 'Your Path Forward');
UPDATE public.lessons SET order_index = -order_index + 1 WHERE order_index < 0;

WITH new_lesson AS (
  INSERT INTO public.lessons (module_number, order_index, title, slug, summary, coin_cost, is_published)
  VALUES (
    7,
    (SELECT order_index FROM public.lessons WHERE module_number = 7 AND title = 'Your Path Forward') - 1,
    'The Hidden Costs of AI: Data, Rights, and Resources',
    'hidden-costs-of-ai-data-rights-resources',
    'Two costs of AI that rarely show up in the interface -- who trained it, who owns what it makes, and what it actually costs to run.',
    10,
    true
  )
  RETURNING id
), ins_content AS (
  INSERT INTO public.lesson_content (lesson_id, content)
  SELECT id, '{"hook":"AI feels free and instant. Behind that feeling: real people''s work, real unsettled copyright questions, and real electricity and water — most of it invisible until you go looking.","explanation":"Two costs of AI rarely show up in the interface. The first is about DATA and RIGHTS: large models are trained on enormous amounts of text, images, and code, much of it scraped from the internet without explicit permission from whoever created it. Whether this is legal is genuinely unsettled — real court cases are deciding it right now, in different ways in different countries, with no final answer yet. It cuts both ways for you as a builder: what a model was trained on can be a real ethical and legal question, AND what YOU get out of a model has its own murky ownership status — in many places, purely AI-generated output with no meaningful human authorship can''t be copyrighted at all. The practical rule: before using AI-generated output commercially (in a paid project, a product, anything public), check the specific tool''s terms of service for what you''re actually allowed to do with what it generates for you — “I made it with AI” doesn''t automatically mean “I own it” or “I''m free to use it however I want.” The second cost is COMPUTE and ENERGY: training a large model, and running billions of everyday queries against it, takes real electricity and real water for cooling data centers. No single query costs much — but at the scale AI runs at today, it adds up to a genuine resource footprint. The practical habit: don''t reach for the biggest, most powerful model by default when a smaller, more efficient one would do the job just as well for the task at hand.","analogy":"It''s like a free public park — the fact that YOUR visit costs nothing doesn''t mean nothing was spent to build and maintain it. Someone''s labor, land, and resources are behind every “free” thing that feels effortless to use.","fun_fact":"Some AI companies have started publishing rough estimates of the energy and water their largest models use — a sign the industry itself now treats this as a real cost worth accounting for, not just a footnote.","try_it":"Before your next AI-assisted project, check two things: whose work likely trained the tool you''re using, and what its terms of service actually say about who owns what it generates for you.","visual":{"caption":"Two real costs that rarely show up in the interface","steps":[{"emoji":"📚","label":"Training Data","caption":"Scraped from the internet — often including copyrighted work, without explicit permission."},{"emoji":"⚖️","label":"Unsettled Law","caption":"Courts are actively deciding whether this is legal — there''s no final answer yet."},{"emoji":"❓","label":"AI Output''s Copyright","caption":"Purely AI-generated content often can''t be copyrighted without real human authorship."},{"emoji":"⚡","label":"Compute & Energy","caption":"Training and running large models takes real electricity and water for cooling."},{"emoji":"🧭","label":"Build Responsibly","caption":"Check terms of service before commercial use; don''t default to the biggest model when a smaller one would do."}]},"practice":{"prompt":"You use an AI tool to generate an image for a paid client project. What should you check first?","options":["The tool''s terms of service for what you''re actually allowed to do with the generated output commercially","Nothing — anything an AI generates is automatically yours to use however you want","Whether the image looks good enough, with no other consideration needed","Only whether the client will notice it was AI-generated"],"correct_index":0,"feedback":"AI-generated output''s ownership status varies by tool and jurisdiction — the terms of service is where that actually gets defined, not assumption."}}'::jsonb FROM new_lesson
  RETURNING lesson_id
)
INSERT INTO public.lesson_quiz_questions (lesson_id, order_index, question, options, correct_index, explanation)
SELECT ins_content.lesson_id, q.order_index, q.question, q.options::jsonb, q.correct_index, q.explanation
FROM ins_content, (VALUES
  (1, 'Why is AI training data a real ethical and legal question?', '["Much of it is scraped from the internet, often including copyrighted work used without explicit permission","AI models are never trained on any real human-created content","This question was fully and permanently settled by courts years ago","Training data has no relationship to copyright at all"]', 0, 'This is genuinely unsettled — real, active court cases are deciding it differently in different places, with no final answer yet.'),
  (2, 'What is true about purely AI-generated output''s copyright status in many places?', '["It often cannot be copyrighted at all without meaningful human authorship","It is always automatically copyrighted to whoever typed the prompt","Copyright law has never addressed AI-generated content in any way","AI-generated output is legally identical to human-created output everywhere"]', 0, 'Many jurisdictions require real human authorship for copyright to apply — purely AI-generated content often falls outside that.'),
  (3, 'What should you check before using AI-generated output in a paid, commercial project?', '["The specific tool''s terms of service for what you''re actually allowed to do with its output","Nothing — commercial use is always automatically fine","Only whether the output looks professional enough","Whether the AI tool itself is popular"]', 0, 'Ownership and usage rights vary by tool and are defined in that tool''s own terms of service, not by assumption.'),
  (4, 'What is the second "hidden cost" of AI covered in this lesson, besides data and rights?', '["Compute and energy -- training and running large models takes real electricity and water","The cost of buying a computer","The cost of an internet subscription","There is no second cost -- data and rights is the only one"]', 0, 'Training and running large models at scale has a real, physical resource footprint, even though any single query feels free.'),
  (5, 'What practical habit does this lesson recommend regarding model size?', '["Don''t default to the biggest, most powerful model when a smaller, more efficient one would do the task just as well","Always use the largest available model for every single task, no exceptions","Model size has no relationship to resource use","Never use AI models above a certain size under any circumstances"]', 0, 'Matching model size to the actual task is a real, practical way to reduce unnecessary compute and energy use.'),
  (6, 'What does the free-public-park analogy in this lesson illustrate?', '["Something that feels effortless or free to use can still have real costs behind it, paid by someone else","Public parks and AI have no meaningful similarities","Everything that is free costs literally nothing to anyone","This analogy is about environmental policy, unrelated to AI"]', 0, 'The park''s upkeep is invisible to a visitor the same way AI''s data and energy costs are invisible to a user typing a prompt.'),
  (7, 'Why does this lesson say training-data legality is "genuinely unsettled" rather than simply illegal or simply fine?', '["Real court cases are actively deciding this question differently across different countries, with no final resolution yet","The question was already fully resolved in favor of AI companies everywhere","The question was already fully resolved against AI companies everywhere","No court has ever addressed this question in any country"]', 0, 'This is live, active, and jurisdiction-dependent -- presenting it as already settled in either direction would be inaccurate.')
) AS q(order_index, question, options, correct_index, explanation);
